  const base="";
   const response=await fetch(base+auth.uploadUrl,{method:"PUT",headers:{Authorization:`Bearer ${token}`,"Content-Type":"application/octet-stream","X-Upload-Token":auth.uploadToken},body:file,cache:"no-store"});
