   {(!renewalMode||hasActiveMembership)&&<div className="grid grid-2">{products.map(p=><div className="membership-plan" key={p.product_code}><div className="row" style={{justifyContent:"space-between",alignItems:"flex-start"}}><div><h3 className="h2">{p.name}</h3><p className="muted">{p.description||"Membership access and benefits are governed by the current MPA plan terms."}</p></div><Badge tone="slate">{p.product_code}</Badge></div><div className="membership-plan__fee"><span>Current total fee</span><strong>{p.currency} {Number(p.price).toLocaleString()}</strong></div>{(Number(p.tax_amount||0)>0||Number(p.service_fee||0)>0)&&<small className="muted">Includes base {p.currency} {Number(p.base_amount??p.price).toLocaleString()}{Number(p.tax_amount||0)>0?` · tax ${p.currency} ${Number(p.tax_amount).toLocaleString()}`:""}{Number(p.service_fee||0)>0?` · service fee ${p.currency} ${Number(p.service_fee).toLocaleString()}`:""}</small>}<p className="muted">Term: {p.billing_model}{p.duration_days?` · ${p.duration_days} days`:""}{p.renewal_required?" · renewal required":" · no recurring renewal"}</p>{Array.isArray(p.benefits)&&p.benefits.length>0&&<div><b>Included benefits</b><ul>{p.benefits.map(benefit=><li key={String(benefit)}>{String(benefit)}</li>)}</ul></div>}{Array.isArray(p.eligibility?.requirements)&&p.eligibility.requirements.length>0&&<div><b>Eligibility</b><ul>{(p.eligibility.requirements as string[]).map(requirement=><li key={requirement}>{requirement}</li>)}</ul></div>}<small className="muted">{p.fee_rule_version?`Plan version ${p.fee_rule_version}`:""}{p.effective_from?` · Effective ${String(p.effective_from).slice(0,10)}`:""}</small>{token?<button type="button" className="btn btn-primary membership-plan__apply" disabled={loading} onClick={()=>{if(productCode!==p.product_code){setEligibilityConfirmed(false);setApplicationStep(1);}setProductCode(p.product_code);setApplicationType(renewalMode?"renewal":"new");setApplicationModalOpen(true);}}>{renewalMode?"Choose renewal plan":"Apply for membership"} <ArrowRight size={16}/></button>:<a className="btn btn-primary membership-plan__apply" href="/login?next=/membership">Sign in to apply <ArrowRight size={16}/></a>}</div>)}</div>}
